// field/components/element.ts
function element(tag, className, text) {
  const made = document.createElement(tag);
  if (className)
    made.className = className;
  if (text !== undefined)
    made.textContent = text;
  return made;
}

// field/components/way.ts
function way(steps) {
  const nav = element("nav");
  for (const step of [{ to: "field", label: "The field" }, ...steps]) {
    const link = element("a", undefined, step.label);
    link.href = "#";
    link.dataset.to = step.to;
    nav.append(link);
  }
  return nav;
}
function follow(root, space) {
  root.addEventListener("click", (event) => {
    const link = event.target.closest("[data-to], a[data-ref]");
    if (!link)
      return;
    event.preventDefault();
    event.stopPropagation();
    space.place(link.dataset.to ?? link.dataset.ref);
  });
}
function card(to) {
  const made = element("div", "card");
  made.tabIndex = 0;
  made.dataset.to = to;
  made.addEventListener("keydown", (event) => {
    if (event.key === "Enter")
      made.click();
  });
  return made;
}

